'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US').format(n||0),date=x=>x?new Date(x).toLocaleString('ar-IQ'):'';
const icon=n=>`<span class="material-symbols-outlined" aria-hidden="true">${n}</span>`;
const roleNames={merchant:'التاجر',courier:'المندوب'};
const vehicleNames={motorcycle:'دراجة نارية',sedan:'سيارة صالون',truck:'سيارة حمل',refrigerated:'سيارة مبردة'};
const natureNames={normal:'عادية',fragile:'قابلة للكسر',food:'طعام',cold:'تحتاج إلى تبريد'};
const before=['draft','published','reserved','approaching','arrived','waiting'],closed=['delivered','returned','cancelled'];
const provinces=['بغداد','البصرة','نينوى','أربيل','النجف','كربلاء','ذي قار','بابل','ديالى','الأنبار','صلاح الدين','واسط','ميسان','المثنى','القادسية','كركوك','السليمانية','دهوك'];
let S=null,screen='home',filter='all',query='',wizard=null,registration=null,installPrompt=null,toastTimer,activeOrder=null;
let offline=false,trackingId=null,lastLocationSent=0;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
async function api(url,data){let r;try{r=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});}catch{offline=true;throw Error('الاتصال بالخادم غير متاح. يمكنك حفظ مسودة على الجهاز.');}const p=await r.json();if(!r.ok)throw Object.assign(Error(p.error||'تعذر الإجراء'),{status:r.status});offline=false;return p;}
function modal(title,content){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=content;if(!$('#app-dialog').open)$('#app-dialog').showModal();}
function closeModal(){$('#app-dialog').close();activeOrder=null;}
function row(label,value){return `<div class="detail-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;}
function button(action,label,extra='',kind='secondary-button'){return `<button type="button" class="${kind}" data-action="${action}" ${extra}>${label}</button>`;}
function input(name,label,value='',attrs=''){return `<label>${label}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;}
function select(name,label,values,value,attrs=''){return `<label>${label}<select name="${name}" ${attrs}>${Object.entries(values).map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function stepper(step,labels){return `<ol class="wizard-steps">${labels.map((label,i)=>`<li class="${i===step?'active':''}"><span>${i<step?'✓':i+1}</span>${label}</li>`).join('')}</ol>`;}
function coords(loc,readonly=false){return `<div class="form-grid">${input('lat','خط العرض',loc?.lat??'',`type="number" step="any" required ${readonly?'readonly':''}`)}${input('lng','خط الطول',loc?.lng??'',`type="number" step="any" required ${readonly?'readonly':''}`)}</div>${readonly?'':button('gps',icon('my_location')+' تحديد موقعي الحالي')}<p class="file-help">الموقع محفوظ بإحداثياته. فتح الخرائط لا يحتاج مشاركة الموقع مع التطبيق.</p>`;}
function maps(loc,label='فتح الموقع بالخرائط'){return loc?`<a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(loc.lat+','+loc.lng)}">${icon('location_on')} ${label}</a>`:'';}
function customerDue(o){return o.amount+(o.feePayer==='customer'?o.fee:0);}
async function refresh(draw=true){try{S=await api('/api/state');localStorage.setItem('wasel-platform-two-role-snapshot',JSON.stringify(S));if(draw)render();}catch(e){if(e.status===401){S=null;loginPage();}else{if(!S){try{S=JSON.parse(localStorage.getItem('wasel-platform-two-role-snapshot'));}catch{}}if(S){offline=true;if(draw)render();}else loginPage(e.message);}}}
let authRole=null;
function splashBike(){return '<g stroke-linecap="round" stroke-linejoin="round"><circle cx="22" cy="53" r="10" fill="#fff" stroke="#00567a" stroke-width="5"/><circle cx="80" cy="53" r="10" fill="#fff" stroke="#00567a" stroke-width="5"/><path d="M10 43q10-16 25-8l13 9h16l8-22h8l5 23H64l-8 11H39q-1-16-21-13" fill="#f47d2f"/><path d="m76 24-5-8h-9" stroke="#00567a" stroke-width="4"/><path d="m48 27-9 9 15 4-2 11h9l3-17-10-7" fill="#004460"/><path d="m46 12-9 16h19l4-12" fill="#00567a"/><path d="m56 17 7 10 10-2" stroke="#00567a" stroke-width="6"/><circle cx="53" cy="7" r="7" fill="#f0b78e"/><path d="M45 7c-2-13 19-13 18 0Z" fill="#00567a"/><path d="M54 0q6 1 7 7" stroke="#f47d2f" stroke-width="3"/><rect x="18" y="15" width="20" height="19" rx="3" fill="#00567a"/><path d="M28 15v19" stroke="#f47d2f" stroke-width="4"/></g>';}
function routeLines(){return `<svg class="entry-route" viewBox="0 0 320 100" fill="none" aria-hidden="true"><path class="route-base" d="M24 76h65c42 0 26-44 70-44h55c40 0 30 44 77 44"/><path class="route-progress" d="M24 76h65c42 0 26-44 70-44h55c40 0 30 44 77 44"/><circle cx="24" cy="76" r="7"/><circle cx="291" cy="76" r="7"/><g class="route-package"><g transform="translate(0,-13)" stroke-linejoin="round"><path d="M0-13 12-7v14L0 13-12 7V-7Z" fill="#f47d2f" stroke="#fff" stroke-width="1.5"/><path d="M-12-7 0-1 12-7M0-1v14" stroke="#00567a" stroke-width="1.5"/><path d="m-6-10 12 6v5" stroke="#fff0e5" stroke-width="3"/></g><animateMotion dur="2.6s" repeatCount="indefinite" path="M24 76h65c42 0 26-44 70-44h55c40 0 30 44 77 44"/></g></svg>`;}
function splashScenery(){return `<svg class="splash-sky" viewBox="0 0 420 100" fill="none" aria-hidden="true"><g stroke="#00567a" stroke-width="1.5" opacity=".22"><path d="M27 48h60c13 0 13-17 1-18-2-23-35-24-39-5-19-4-26 12-22 23Z"/><path d="M297 37h58c16 0 15-19 0-20-6-17-26-17-33-3-16-5-28 9-25 23Z"/><path d="m184 30 9-9 9 9v15h-18Z"/><path d="M191 45V34h5v11"/></g><g stroke="#f47d2f" stroke-width="2" opacity=".55"><path d="M125 67h12m-6-6v12M270 61h10m-5-5v10"/><circle cx="364" cy="72" r="4"/></g></svg><svg class="splash-city" viewBox="0 0 600 160" fill="none" aria-hidden="true"><g fill="#00567a" opacity=".08"><path d="M0 130V76h45v54m13 0V42h48v88m15 0V64h49v66m245 0V58h51v72m15 0V31h45v99m14 0V81h60v49"/><path d="M70 42V28h22v14m400-11V17h22v14"/></g><g stroke="#00567a" opacity=".15" stroke-width="2"><path d="M0 133h600M69 57h26m-26 14h26m330 4h30m-30 14h30M492 48h22m-22 15h22"/></g><path class="city-road" d="M0 150h600" stroke="#f47d2f" stroke-width="2" stroke-dasharray="18 20" opacity=".38"/><g class="city-rider"><g transform="translate(220,59) scale(1.15)">${splashBike()}</g></g></svg>`;}
function showWelcomeSplash(){
 document.body.classList.add('auth-mode','entry-boot');
 const splash=document.createElement('div');splash.className='welcome-splash glass-splash';splash.setAttribute('role','status');splash.setAttribute('aria-label','مرحباً بك في واصل');
 splash.innerHTML=`${splashScenery()}<div class="splash-content"><span class="auth-logo-art" role="img" aria-label="شعار واصل"></span><strong>واصل</strong><span class="splash-english">ALWASIL DELIVERY</span><p>من بابك… لكل وجهة</p>${routeLines()}</div>`;
 document.body.append(splash);
 return new Promise(resolve=>setTimeout(()=>{splash.classList.add('leaving');document.body.classList.remove('entry-boot');resolve();setTimeout(()=>splash.remove(),400);},matchMedia('(prefers-reduced-motion: reduce)').matches?700:3000));
}
function loginPage(error=''){
 document.body.classList.add('auth-mode');$('#header-actions').innerHTML='';$('#bottom-nav').hidden=true;
 const brand=`<div class="entry-brand"><span class="auth-logo-art" role="img" aria-label="شعار واصل"></span><strong>واصل</strong><span>ALWASIL · FOR DELIVERY</span></div>`;
 const roles=`<div class="entry-intro"><span class="entry-kicker">كل مشوار يبدأ بخطوة</span><h1>حيّاك بواصل</h1><p>اختار حسابك، وخلّي الباقي علينا.</p></div><div class="glass-role-grid">${['merchant','courier'].map(r=>`<button type="button" class="glass-role ${r}" data-action="choose-role" data-role="${r}"><span class="glass-role-icon">${icon(r==='merchant'?'storefront':'two_wheeler')}</span><strong>${roleNames[r]}</strong><span class="role-description">${r==='merchant'?'طلباتك بيد أمينة':'كل مشوار، فرصة جديدة'}</span><span class="role-enter">دخول ${roleNames[r]} ${icon('arrow_back')}</span></button>`).join('')}</div><div class="entry-promise"><span>${icon('bolt')}سهل وسريع</span><span>${icon('route')}معك بكل خطوة</span></div>`;
 const form=authRole?`<section class="glass-login" aria-labelledby="login-title">${button('choose-again',icon('arrow_forward')+' تغيير نوع الحساب','','entry-back')}<div class="selected-role-icon ${authRole}">${icon(authRole==='merchant'?'storefront':'two_wheeler')}</div><span class="entry-kicker">حساب ${roleNames[authRole]}</span><h1 id="login-title">نورتنا من جديد</h1><p class="login-subtitle">أدخل بياناتك وابدأ مشوارك.</p><form id="login-form" class="form-stack"><input type="hidden" name="role" value="${authRole}">${input('phone','رقم الهاتف','','required type="tel" dir="ltr" inputmode="tel" autocomplete="username" placeholder="077xxxxxxxx"')}<div class="login-password">${input('password','كلمة المرور','','required type="password" autocomplete="current-password" placeholder="أدخل كلمة المرور"')}${button('toggle-password',icon('visibility'),'aria-label="إظهار كلمة المرور" aria-pressed="false"','password-toggle')}</div><p class="inline-error" role="alert">${esc(error)}</p><button class="login-submit" type="submit">تسجيل الدخول ${icon('arrow_back')}</button></form><p class="login-create">أول مرة ويانا؟ ${button('register','أنشئ حسابك','','auth-text-button')}</p><details class="login-demo"><summary>تجربة الحساب ${icon('expand_more')}</summary><p>حساب تجريبي للفحص</p>${button('demo','فتح حساب '+roleNames[authRole]+' التجريبي',`data-role="${authRole}"`,'full-width secondary-button')}</details></section>`:'';
 $('#app').innerHTML=`<div class="glass-entry ${authRole?'is-login':''}"><div class="glass-orb orb-blue" aria-hidden="true"></div><div class="glass-orb orb-orange" aria-hidden="true"></div><div class="entry-content">${brand}${authRole?form:roles}<p class="entry-signature">توصيل أسرع… لحياة أسهل</p></div></div>`;
 window.scrollTo(0,0);
}

async function login(role,phone,password){await api('/api/login',{role,phone,password});screen='home';filter='all';history.replaceState(null,'',`/${role}/`);document.querySelector('link[rel=manifest]').href=`/${role}/manifest.webmanifest`;await refresh();}
function navIcon(key){const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',registry:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 8h6M9 12h6M9 16h3"/>',new:'<path d="M12 5v14M5 12h14"/>',wallet:'<path d="M20 8V6a2 2 0 0 0-2-2H6a3 3 0 0 0 0 6h14v10H6a3 3 0 0 1-3-3V7"/><path d="M20 12h-5a2 2 0 0 0 0 4h5"/>',account:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',available:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>'};return '<span class="nav-symbol"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[key]+'</svg></span>';}
function nav(){const r=S.user.role;const list=r==='merchant'?[['home','home','الرئيسية'],['registry','receipt_long','السجل'],['new','add','طلب جديد'],['wallet','account_balance_wallet','المحفظة'],['account','storefront','حسابي']] :[['home','home','الرئيسية'],['available','travel_explore','المتاح'],['registry','local_shipping','طلباتي'],['wallet','account_balance_wallet','المحفظة'],['account','person','حسابي']];const bar=$('#bottom-nav');bar.hidden=false;if(bar.dataset.role!==r){bar.dataset.role=r;bar.innerHTML=`<div>${list.map(([key,ic,label])=>`<button type="button" data-action="nav" data-screen="${key}" class="${key==='new'?'new':''}">${navIcon(key)}<span>${label}</span></button>`).join('')}</div>`;}for(const b of bar.querySelectorAll('button')){const active=b.dataset.screen===screen;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}}
function render(){stopWalletMotion();if(!S)return loginPage();document.body.classList.remove('auth-mode');const u=S.user;$('#role-badge').textContent=roleNames[u.role];$('#page-title').textContent={home:'لوحة '+roleNames[u.role],registry:'سجل الطلبات',available:'الطلبات المتاحة',wallet:'المحفظة',account:'حسابي',new:'طلب جديد',register:'تسجيل الحساب'}[screen]||'واصل';$('#header-actions').innerHTML=button('notifications',icon('notifications'),'aria-label="الإشعارات"','icon-button')+button('logout',icon('logout'),'aria-label="تسجيل الخروج"','icon-button');nav();
 let content=screen==='new'?orderWizard():screen==='account'?accountView():screen==='wallet'?walletView():screen==='registry'||screen==='available'?ordersView():homeView();
 $('#app').innerHTML=`<div class="demo-notice"><span>بيئة محلية • ${esc(u.id)} • ${u.approved?'حساب معتمد':'الحساب غير نشط'}</span>${button('install','تثبيت التطبيق')}</div>${offline?'<p class="status-note">الخادم غير متاح — المعروض آخر نسخة محفوظة. الإجراءات المشتركة تحتاج الاتصال.</p>':''}${content}`;
 initWalletMotion();
}
function metric(label,value,caption,ic,color=''){return `<div class="metric ${color}"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${value}</div><small>${caption}</small></div>`;}
function homeView(){const u=S.user;
 const own=S.orders.filter(o=>u.role==='merchant'||o.courier===u.id),active=own.filter(o=>!before.includes(o.status)&&!closed.includes(o.status)).length,pickup=own.filter(o=>['reserved','approaching','arrived','waiting'].includes(o.status)).length,returns=own.filter(o=>['failed','return_pending','returning','partial_pending'].includes(o.status)).length;
 return `<section class="surface"><div class="row"><div><h2>${esc(u.name)}</h2><p class="muted">${icon('location_on')} ${esc(u.province)}، ${esc(u.area)} <b>• ${esc(u.id)}</b></p></div>${button('refresh',icon('sync'),'aria-label="تحديث البيانات"','icon-button')}</div>${u.role==='merchant'?`<div class="order-strip" style="margin-top:14px"><div><strong>${S.couriers.length} مناديب متاحين ضمن20 كم</strong><p class="muted">حسب آخر موقع مسجل في النسخة المحلية</p></div>${button('nearby','عرض المواقع')}</div>`:`<div class="order-strip" style="margin-top:14px"><div><strong>${u.available?'متاح لاستلام الطلبات':'غير متاح حالياً'}</strong><p class="muted">الميزانية ${money(u.budget)} د.ع • نطاق ${u.radius} كم</p></div>${button('readiness','تحديث الجاهزية')}${button('tracking',trackingId===null?'مشاركة الموقع أثناء العمل':'إيقاف مشاركة الموقع')}</div>${u.restrictedUntil&&Date.parse(u.restrictedUntil)>Date.now()?`<p class="status-note">الحجوزات الجديدة مقيّدة حتى ${date(u.restrictedUntil)}. يمكنك إكمال الشحنات بعهدتك.</p>`:''}`}</section><div class="metrics-grid">${metric('شحنات نشطة',active,'بعهدة المندوب','local_shipping')}${metric('قبل الاستلام',pickup,'حجوزات قيد المتابعة','inventory_2','orange')}${metric('رصيد المحفظة',money(S.balance),'د.ع • منفصل عن قيمة البضاعة','payments')}${metric('تعذر ومرتجعات',returns,'تحتاج متابعة وتسوية','assignment_return','red')}</div>${u.role==='merchant'?`<div class="row"><h2 class="section-title">الشحنات المباشرة</h2>${button('nav','عرض السجل','data-screen="registry"')}</div>`:'<h2 class="section-title">الطلبات بعهدتي</h2>'}${statusPicker()}${orderList(own.filter(o=>filter==='all'?!closed.includes(o.status):o.status===filter).slice(0,10))}${u.role==='merchant'?`<section class="express-card" aria-labelledby="express-title"><div class="express-copy"><div class="express-heading"><span class="express-badge">شحن<br>فوري</span><h3 id="express-title">توصيل حر<br>ومستعجل؟</h3></div><p>احجز أقرب كابتن فوري لشحنة<br class="express-break"> سريعة بدون جدولة زمنية.</p></div>${button('new-free','طلب كابتن <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3 4l18 8-18 8V4Zm0 8h18" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/></svg>','','express-button')}</section>`:''}`;
}
function statusPicker(){const options=[['all','جميع الحالات'],...Object.entries(S.statuses)];return `<div class="status-picker"><button id="status-trigger" class="status-trigger" data-action="filter-open" aria-haspopup="listbox" aria-controls="status-menu" aria-expanded="false">${icon('filter_list')}<span>${esc(S.statuses[filter]||'جميع الحالات')}</span><span class="status-trigger-count">${baseOrders().filter(o=>filter==='all'||o.status===filter).length}</span>${icon('expand_more')}</button><div id="status-menu" popover="auto" class="status-menu"><div class="status-menu-heading">حالة الشحنة<span>عدد الطلبات</span></div><div role="listbox" aria-label="حالة الشحنة">${options.map(([v,label])=>`<button role="option" aria-selected="${filter===v}" tabindex="${filter===v?0:-1}" data-action="filter" data-value="${v}" class="status-option status-${v}"><span class="status-icon material-symbols-outlined" aria-hidden="true">${v==='all'?'filter_list':v.startsWith('return')?'assignment_return':v==='delivered'?'check_circle':v==='cancelled'?'cancel':v==='draft'?'edit_note':'local_shipping'}</span><span class="status-option-label">${label}</span><span class="status-check material-symbols-outlined" aria-hidden="true">check</span><span class="status-badge">${baseOrders().filter(o=>v==='all'||o.status===v).length}</span></button>`).join('')}</div></div></div>`;}
function baseOrders(){return S.orders.filter(o=>screen==='available'?o.status==='published':S.user.role==='courier'?o.courier===S.user.id:true);}
function ordersView(){const os=baseOrders().filter(o=>(filter==='all'||o.status===filter)&&(!query||JSON.stringify([o.id,o.recipient,o.sender]).includes(query)));return `<section class="search-row"><input id="order-search" aria-label="البحث عن طلب" placeholder="ابحث برقم الطلب أو الاسم أو المنطقة" value="${esc(query)}">${statusPicker()}${screen==='available'?button('merchant-map',icon('map')+' تجميع حسب الموقع'):''}</section><p class="info-line">${os.length} طلب ${screen==='available'?'يناسب الموقع والمركبة والميزانية':''}</p>${orderList(os)}`;}
function orderList(os){return os.length?os.map(o=>`<article class="order-card"><div class="order-top"><div class="order-id"><span class="order-index">${icon(o.kind==='free'?'bolt':'inventory_2')}</span><h3>${esc(o.id)}</h3></div><span class="chip ${o.status}">${esc(S.statuses[o.status])}</span></div><div class="order-strip"><div><strong>${esc(o.recipient.name||'بيانات المستلم تظهر بعد الاستلام')}</strong><p class="muted">${esc(o.sender.area||o.sender.province)} ← ${esc(o.recipient.area)} • ${vehicleNames[o.vehicle]}</p></div>${o.service==='vip'?'<span class="chip pickup">VIP</span>':''}</div><div class="money-grid"><div><span>البضاعة</span><strong>${money(o.amount)} د.ع</strong></div><div><span>التوصيل</span><strong>${money(o.fee)} د.ع</strong></div><div><span>أجرة الراجع</span><strong>${money(o.returnFee)} د.ع</strong></div></div><div class="order-bottom"><span class="muted">${o.count} قطع • ${o.weight} كغم • الأجرة على ${o.feePayer==='merchant'?'التاجر':'الزبون'} ${o.settled?'• مسوّى':''}</span>${button('order','تفاصيل الطلب',`data-id="${o.id}"`)}</div></article>`).join(''):'<div class="empty">لا توجد طلبات بهذه الحالة</div>';}
function availableActions(o){const own=S.user.id===o.merchant,assigned=S.user.id===o.courier,entries=[];const add=(action,label)=>entries.push([action,label]);if(own){if(before.includes(o.status)){add('edit','تعديل الطلب');if(o.status==='draft'){add('publish','نشر الطلب');add('delete','حذف المسودة');}else{if(o.status==='published'){add('unpublish','إلغاء النشر');add('raise_fee','أنا مستعجل — زيادة الأجرة');}add('cancel','إلغاء الطلب');}}if(o.status==='retry'&&!o.retryApproved)add('approve_retry','الموافقة على الموعد');if(o.status==='at_customer'&&o.partial&&!o.partial.approved)add('partial_approve','الموافقة على التسليم الجزئي');if(['failed','retry'].includes(o.status))add('return','طلب إرجاع الشحنة');if(o.status==='returning'&&o.returnArrived&&!o.returnReceived)add('receive_return','تأكيد استلام المرتجع');}
 if(S.user.role==='courier'&&o.status==='published'){add('reserve','حجز الطلب');add('offer','اقتراح أجرة');}if(assigned){if(o.status==='reserved')add('depart','أنا في الطريق');if(['reserved','approaching'].includes(o.status)){add('arrive','وصلت إلى موقع الاستلام');if(!o.extended)add('extend','تمديد المهلة');}if(['reserved','approaching','arrived','waiting'].includes(o.status))add('release','إلغاء الحجز مع سبب');if(o.status==='arrived')add('wait','بانتظار تجهيز الشحنة');if(['arrived','waiting'].includes(o.status))add('pickup','فحص ودفع واستلام');if(o.status==='received')add('transit','بدء التوصيل');if(o.status==='transit'||(o.status==='retry'&&o.retryApproved))add('customer_arrive','وصلت إلى الزبون');if(o.status==='at_customer'){add('deliver','تأكيد التسليم والتحصيل');if(S.settings.partialEnabled&&o.kind!=='free'){if(!o.partial)add('partial_propose','اقتراح تسليم جزئي');if(o.partial?.approved)add('partial_confirm','تأكيد الجزء المسلم');}}if(['transit','at_customer','retry'].includes(o.status))add('fail','تعذر التسليم');if(o.status==='failed'){if(o.attempts<S.settings.maxAttempts)add('retry','اقتراح إعادة المحاولة');add('return','بدء مسار الإرجاع');}if(['return_pending','partial_pending'].includes(o.status))add('return_start','التوجه لإرجاع الشحنة');if(o.status==='returning'){if(!o.returnArrived)add('return_arrive','وصلت بالمرتجع');if(o.returnReceived)add('settle_return','تأكيد استرداد القيمة والأجور');}if(o.status==='delivered'&&!o.settled)add('settle_delivery','تأكيد التسوية مع المرسل');}
 if((own||assigned)&&o.courier)add('chat','محادثة هذا الطلب');if((own||assigned)&&closed.includes(o.status)&&o.status!=='cancelled'&&o.settled&&!S.ratings.some(r=>r.owner===S.user.id&&r.orderId===o.id))add('rate','تقييم الطرف الآخر');return entries;}
function orderDetail(oid){const o=S.orders.find(o=>o.id===oid);if(!o)return;activeOrder=oid;const isOwn=o.merchant===S.user.id;const offers=S.offers.filter(x=>x.orderId===oid);modal(o.id,`${o.demo?'<p class="status-note">طلب تجريبي محلي؛ لا يمثل شحنة حقيقية.</p>':''}<span class="chip ${o.status}">${S.statuses[o.status]}</span>${row('المرسل',o.sender.name)}${row('المستلم',o.recipient.name||'محجوب حتى الاستلام')}${row('عنوان التسليم',o.recipient.address||o.recipient.area)}${o.recipient.landmark?row('نقطة دالة',o.recipient.landmark):''}${row('تفاصيل الشحنة',`${o.count} قطع • ${o.weight} كغم • ${o.length}×${o.width}×${o.height} سم`)}${row('الطبيعة والمركبة',natureNames[o.nature]+' • '+vehicleNames[o.vehicle])}${row('قيمة البضاعة',money(o.amount)+' د.ع')}${row('أجرة التوصيل',money(o.fee)+' د.ع — على '+(o.feePayer==='merchant'?'التاجر':'الزبون'))}${row('أجرة الراجع',money(o.returnFee)+' د.ع')}${row('المطلوب من الزبون',money(customerDue(o))+' د.ع')}${row('تسوية الأموال',o.settled?'مكتملة':'غير مكتملة')}${o.notes?row('الملاحظات',o.notes):''}${o.courierInfo?.photo?`<div class="photo-preview"><img alt="صورة المندوب" src="${esc(o.courierInfo.photo)}"></div>`:''}${o.courierInfo?row('المندوب',o.courierInfo.name+' • '+vehicleNames[o.courierInfo.vehicle]+' • '+o.courierInfo.plate):''}${isOwn&&o.handoverCode&&before.includes(o.status)?`<div class="review-group"><h3>رمز الاستلام</h3><p class="code">${o.handoverCode}</p><p class="muted">أعطه للمندوب بعد الفحص واستلام قيمة البضاعة فقط.</p></div>`:''}${o.deadline&&['reserved','approaching'].includes(o.status)?`<p class="status-note blue">مهلة الوصول حتى ${date(o.deadline)} — تقدير محلي بناءً على المسافة المباشرة، وليس زمن طريق فعلياً.</p>`:''}${o.retryAt?row('موعد إعادة المحاولة',date(o.retryAt)+(o.retryApproved?' — معتمد':' — بانتظار الموافقة')):''}${o.partial?row('الجزء المقترح',o.partial.count+' قطع / '+money(o.partial.amount)+' د.ع'):''}<div class="contact-actions" style="margin:14px 0">${maps(o.sender.location,'موقع الاستلام')}${!isOwn?`<a href="tel:${o.sender.phone}">اتصال بالمرسل</a><a target="_blank" rel="noopener noreferrer" href="https://wa.me/964${o.sender.phone.slice(1)}">واتساب المرسل</a>`:''}${maps(o.recipient.location,'موقع التسليم')}${o.courierInfo?`<a href="tel:${o.courierInfo.phone}">${icon('phone')} المندوب</a><a target="_blank" rel="noopener noreferrer" href="https://wa.me/964${o.courierInfo.phone.slice(1)}">واتساب المندوب</a>`:''}${o.recipient.phone?`<a href="tel:${o.recipient.phone}">${icon('phone')} المستلم</a>`:''}${isOwn&&o.recipient.phone&&!before.includes(o.status)?`<a target="_blank" rel="noopener noreferrer" href="https://wa.me/964${o.recipient.phone.slice(1)}?text=${encodeURIComponent('تم تسليم طلبك '+o.id+' إلى المندوب وهو الآن في طريقه إليك.')}">تجهيز رسالة الزبون</a>`:''}</div>${o.photo?`<div class="photo-preview"><img src="${esc(o.photo)}" alt="صورة الشحنة"></div>`:''}<div class="order-actions">${availableActions(o).map(([action,label])=>button('order-action',label,`data-id="${oid}" data-op="${action}"`,['cancel','release','delete'].includes(action)?'secondary-button danger':'secondary-button')).join('')}</div>${isOwn&&o.status==='published'&&offers.length?`<h3 class="section-title">عروض المندوبين</h3>${offers.map(v=>`<div class="detail-row"><span>${esc(v.name)} — ${money(v.fee)} د.ع</span>${button('order-action','قبول العرض',`data-id="${oid}" data-op="accept_offer" data-offer="${v.id}"`)}</div>`).join('')}`:''}<h3 class="section-title">سجل الطلب</h3><ol class="timeline">${o.history.slice().reverse().map(h=>`<li>${esc(h.text)}<small>${date(h.at)} • ${esc(h.actor)}</small></li>`).join('')}</ol>`);}
function startOrder(kind='merchant',old=null){wizard={step:0,id:old?.id,data:old?structuredClone(old):{kind,amount:0,count:1,weight:1,length:20,width:20,height:20,nature:'normal',vehicle:'sedan',baseFee:5000,fee:5000,returnFee:0,feePayer:'customer',service:'normal',collection:'none',notes:'',sender:{...S.user},recipient:{province:S.user.province,name:'',phone:'',phone2:'',area:'',address:'',landmark:''}}};screen='new';closeModal();render();window.scrollTo(0,0);}
function orderWizard(){if(!wizard)return '<div class="empty">ابدأ طلباً جديداً من شريط التنقل.</div>';const d=wizard.data,r=d.recipient,u=S.user;let fields='';if(wizard.step===0){fields=`<div class="form-grid">${d.kind==='free'?select('collection','نوع التوصيل الحر',{none:'توصيل فقط دون تحصيل',collect:'توصيل مع تحصيل مبلغ'},d.collection):''}${input('amount','قيمة البضاعة (د.ع)',d.amount,'type="number" min="0" max="100000000" required')}${input('count','عدد القطع',d.count,'type="number" min="1" max="1000" required')}${input('weight','الوزن (كغم)',d.weight,'type="number" min="0.1" step="0.1" required')}${input('length','الطول (سم)',d.length,'type="number" min="1" required')}${input('width','العرض (سم)',d.width,'type="number" min="1" required')}${input('height','الارتفاع (سم)',d.height,'type="number" min="1" required')}${select('nature','طبيعة الشحنة',natureNames,d.nature)}${select('vehicle','المركبة المناسبة',vehicleNames,d.vehicle)}${select('service','نوع الخدمة',{normal:'عادي',vip:'VIP — مندوب مخصص'},d.service)}${input('baseFee','أجرة التوصيل العادي (د.ع)',d.baseFee,'type="number" min="0" required')}${select('feePayer','من يتحمل أجرة التوصيل؟',{customer:'الزبون',merchant:'التاجر / المرسل'},d.feePayer)}${input('returnFee','أجرة الراجع (د.ع)',d.returnFee,'type="number" min="0" required')}</div><p class="status-note blue">تُضاف ${money(S.settings.vipSurcharge)} د.ع لأجرة VIP. أجرة الراجع لا تتجاوز أجرة التوصيل.</p>`;}else if(wizard.step===1){fields=d.kind==='free'?`${input('senderName','اسم المرسل',d.sender.name,'required maxlength="80"')}${input('senderPhone','هاتف المرسل',d.sender.phone,'required type="tel" dir="ltr"')}${input('senderAddress','عنوان المرسل',d.sender.address,'required maxlength="200"')}${coords(d.sender.location)}<label>صورة الشحنة من الكاميرا<input name="photo" type="file" accept="image/*" capture="environment" ${d.photo?'':'required'}></label>${d.photo?'<p class="file-help">صورة مرفقة. اختر صورة أخرى لاستبدالها.</p>':''}<p class="status-note">لا يُدفع مبلغ الشحنة للمرسل مقدماً في التوصيل الحر؛ هذه السياسة بانتظار اعتماد مستقل.</p>`:`<p class="muted">تُعبّأ هذه البيانات من الملف المعتمد، ويرتبط الطلب بموقع النشاط المحفوظ.</p>${row('المعرف الثابت',u.id)}${row('اسم النشاط',u.name)}${row('المحافظة والمنطقة',u.province+' — '+u.area)}${row('العنوان',u.address)}${row('الهاتف',u.phone)}${row('هاتف احتياطي',u.phone2||'غير مضاف')}<div class="contact-actions">${maps(u.location)}</div>`;}else if(wizard.step===2){fields=`${(u.customers||[]).length?select('savedCustomer','استخدام بيانات زبون سابق',{'':'زبون جديد',...Object.fromEntries(u.customers.map((r,i)=>[String(i),r.name+' — '+r.phone]))},''):''}<div class="form-grid">${input('name','اسم المستلم',r.name,'required maxlength="80" autocomplete="name"')}${input('phone','رقم الهاتف',r.phone,'required type="tel" dir="ltr"')}${input('phone2','رقم إضافي (اختياري)',r.phone2,'type="tel" dir="ltr"')}${input('province','المحافظة',u.province,'readonly')}${input('area','المنطقة',r.area,'required maxlength="80"')}${input('address','العنوان',r.address,'required maxlength="200"')}${input('landmark','أقرب نقطة دالة',r.landmark,'maxlength="200"')}${input('lat','خط عرض المستلم (اختياري)',r.location?.lat??'','type="number" step="any"')}${input('lng','خط طول المستلم (اختياري)',r.location?.lng??'','type="number" step="any"')}</div><label>ملاحظات التوصيل<textarea name="notes" maxlength="500">${esc(d.notes)}</textarea></label>`;}else{fields=`<div class="review-group"><h3>المرسل والمستلم</h3><p>${esc(d.kind==='free'?d.sender.name:u.name)} ← ${esc(r.name)}</p><p>${esc(r.province)}، ${esc(r.area)}، ${esc(r.address)}</p><p>${esc(r.phone)} ${r.phone2?' / '+esc(r.phone2):''}</p></div><div class="review-group"><h3>تفاصيل الشحنة</h3><p>${d.count} قطع • ${d.weight} كغم • ${d.length}×${d.width}×${d.height} سم</p><p>${natureNames[d.nature]} • ${vehicleNames[d.vehicle]} • ${d.service==='vip'?'VIP':'عادي'}</p></div>${row('قيمة البضاعة',money(d.amount)+' د.ع')}${row('أجرة التوصيل',money(d.fee)+' د.ع — على '+(d.feePayer==='merchant'?'التاجر':'الزبون'))}${row('أجرة الراجع',money(d.returnFee)+' د.ع')}${row('المطلوب من الزبون',money(customerDue(d))+' د.ع')}${row('الملاحظات',d.notes||'لا توجد')}${wizard.id?'<p class="status-note">تعديل الطلب المحجوز يلغي الحجز السابق ويعيد نشره، دون احتسابه إلغاءً على المندوب.</p>':''}<p class="muted">النشر يجعل الطلب متاحاً للمندوبين المناسبين داخل هذه المنظومة المحلية.</p>`;}
 return `<section class="surface wizard">${stepper(wizard.step,['الشحنة','المرسل','المستلم','المراجعة'])}<h2 style="margin-bottom:16px">${wizard.id?'تعديل الطلب':d.kind==='free'?'طلب توصيل حر':'إنشاء طلب جديد'}</h2><form id="order-form" class="form-stack">${fields}<p class="inline-error" id="form-error"></p><div class="wizard-footer">${wizard.step?button('wizard-back','السابق'):button('nav','إلغاء','data-screen="home"')}${wizard.step<3?'<button class="primary-button" type="submit">التالي</button>':`${button('save-order',wizard.id?'حفظ التعديل':'حفظ دون نشر','data-publish="false"','secondary-button')}${wizard.id?'':button('save-order','نشر الطلب','data-publish="true"','primary-button')}`}</div></form></section>`;}
function gatherOrder(form){const f=Object.fromEntries(new FormData(form)),d=wizard.data;if(wizard.step===0){for(const key of ['amount','count','weight','length','width','height','baseFee','returnFee'])d[key]=Number(f[key]);for(const key of ['nature','vehicle','service','feePayer'])d[key]=f[key];d.collection=f.collection||d.collection;d.fee=d.baseFee+(d.service==='vip'?S.settings.vipSurcharge:0);if(d.kind==='free'&&d.collection==='none')d.amount=0;if(d.returnFee>d.fee)throw Error('أجرة الراجع لا تتجاوز أجرة التوصيل');if(d.nature==='cold'&&d.vehicle!=='refrigerated')throw Error('الشحنة المبردة تحتاج سيارة مبردة');}else if(wizard.step===1&&d.kind==='free'){d.sender={name:f.senderName,phone:f.senderPhone,address:f.senderAddress,province:S.user.province,location:{lat:Number(f.lat),lng:Number(f.lng)}};}else if(wizard.step===2){d.recipient={name:f.name,phone:f.phone,phone2:f.phone2,province:S.user.province,area:f.area,address:f.address,landmark:f.landmark,location:f.lat&&f.lng?{lat:Number(f.lat),lng:Number(f.lng)}:null};if(!!f.lat!==!!f.lng)throw Error('أدخل خط العرض والطول معاً');d.notes=f.notes;}}
function accountView(){const u=S.user;return `<section class="surface"><h2>${esc(u.name)}</h2>${row('معرف الدور الثابت',u.id)}${row('معرف المحفظة',u.walletId)}${row('الهاتف',u.phone)}${row('الدور',roleNames[u.role])}${row('العنوان',u.province+' — '+u.area+' — '+u.address)}${S.profileLocked?`<p class="profile-lock">${icon('lock')} تعديل الملف مقفل حتى إكمال الطلبات والمرتجعات وتسوياتها المالية.</p>`:button('edit-profile','تعديل الملف')}<div class="contact-actions" style="margin-top:14px">${maps(u.location)}</div></section><section class="surface"><h3>التقييمات</h3>${S.ratings.filter(r=>r.target===u.id).map(r=>`<p class="info-line">${'★'.repeat(r.stars)} — ${esc(r.text)} (${esc(r.orderId)})</p>`).join('')||'<p class="muted">لا توجد تقييمات بعد.</p>'}</section><section class="surface"><h3>التنبيهات التحفيزية</h3><p class="muted">إشعارات الطلبات الجارية تبقى ظاهرة في سجل الإشعارات.</p>${button('preferences',u.motivational===false?'تفعيل تنبيهات الطلبات القريبة':'إيقاف تنبيهات الطلبات القريبة')}</section>${offlineDraftsView()}`;}
function walletView(){const credits=S.ledger.reduce((n,r)=>n+Math.max(0,r.amount),0),debits=S.ledger.reduce((n,r)=>n+Math.max(0,-r.amount),0);return `<section class="orbit-wallet" aria-labelledby="orbit-title"><div class="orbit-grid" aria-hidden="true"></div><header class="orbit-top"><div><span class="orbit-eyebrow">WASEL WALLET</span><h2 id="orbit-title">محفظتك، بكل وضوح</h2></div><span class="orbit-wallet-icon" aria-hidden="true">${icon('account_balance_wallet')}</span></header><div class="orbit-center"><svg class="orbit-rings" viewBox="0 0 300 250" fill="none" aria-hidden="true"><ellipse cx="150" cy="125" rx="133" ry="104" stroke="#ffffff12"/><circle cx="150" cy="125" r="99" stroke="#ffffff0f" stroke-width="18"/><path d="M58 87a99 99 0 0 1 185 75" stroke="#f47d2f" stroke-width="3" stroke-linecap="round"/><path d="M242 162a99 99 0 0 1-166 29" stroke="#78c9e2" stroke-opacity=".3" stroke-width="2" stroke-dasharray="2 7"/><circle cx="58" cy="87" r="6" fill="#f47d2f"/><circle cx="243" cy="162" r="6" fill="#f47d2f"/><circle cx="243" cy="162" r="12" stroke="#f47d2f" stroke-opacity=".25"/></svg><div class="orbit-balance"><span>الرصيد الحالي</span><strong dir="ltr">${money(S.balance)}</strong><small>دينار عراقي</small><span class="orbit-account-type">محفظة تشغيلية</span></div></div><div class="orbit-flows"><div><span class="orbit-flow-label"><i class="orbit-flow-icon incoming">${icon('south_west')}</i>إجمالي الإضافات</span><strong dir="ltr">${money(credits)}<small> IQD</small></strong></div><span class="orbit-flow-divider" aria-hidden="true"></span><div><span class="orbit-flow-label"><i class="orbit-flow-icon outgoing">${icon('north_east')}</i>إجمالي الخصومات</span><strong dir="ltr">${money(debits)}<small> IQD</small></strong></div></div><footer class="orbit-footer"><div class="orbit-owner"><span>صاحب المحفظة</span><strong>${esc(S.user.name)}</strong></div>${button('wallet-statement','كشف الحركة '+icon('arrow_back'),'','orbit-statement')}</footer>${button('copy-wallet','<span dir="ltr">'+esc(S.user.walletId)+'</span>'+icon('content_copy'),'aria-label="نسخ رقم المحفظة"','orbit-copy')}</section><section class="surface"><p class="info-line">${S.settings.freeService?'الخدمة مجانية حالياً.':'عمولة الطلب '+money(S.settings.commission)+' د.ع • الاشتراك '+money(S.settings.subscription)+' د.ع'}</p><p class="muted">رصيد المحفظة مستقل عن ميزانية المندوب وقيمة البضاعة المدفوعة نقداً. تظهر هنا الحركات المسجلة فقط.</p></section><section class="surface"><h3>حركات المحفظة</h3>${ledger(S.ledger)}</section><section class="surface"><h3>سجل البضاعة والتحصيل والأجور</h3>${ledger(S.cashLedger)}</section>`;}

function ledger(items){return items.length?`<div style="overflow:auto"><table class="ledger"><thead><tr><th>البيان</th><th>المبلغ</th><th>الطلب والتاريخ</th></tr></thead><tbody>${items.map(r=>`<tr><td>${esc(r.reason)}</td><td class="${r.amount>=0?'positive':'negative'}" dir="ltr">${money(r.amount)}</td><td>${esc(r.orderId||'—')}<br><small>${date(r.at)}</small></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted" style="margin-top:12px">لا توجد حركات مسجلة.</p>';}
function offlineDraftsView(){const drafts=readDrafts();return `<section class="surface"><h3>مسودات غير متزامنة</h3><p class="muted">مسودات محفوظة على هذا الجهاز فقط: ${drafts.length}</p>${drafts.map((d,i)=>`<div class="detail-row"><span>${esc(d.recipient.name)}</span>${button('sync-draft','حفظ بالخادم دون نشر',`data-index="${i}"`)}</div>`).join('')}</section>`;}
function readDrafts(){try{return JSON.parse(localStorage.getItem('wasel-offline-'+S.user.id)||'[]');}catch{return [];}}
async function imageData(file){if(!file)return null;if(!file.type.startsWith('image/'))throw Error('اختر ملف صورة');if(file.size>15000000)throw Error('حجم الصورة كبير');return new Promise((resolve,reject)=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{const ratio=Math.min(1,900/Math.max(image.width,image.height));const c=document.createElement('canvas');c.width=image.width*ratio;c.height=image.height*ratio;c.getContext('2d').drawImage(image,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',.75));};image.onerror=()=>{URL.revokeObjectURL(url);reject(Error('تعذرت قراءة الصورة'));};image.src=url;});}
function registrationView(){if(registration.role==='courier')return courierRegistrationView();document.body.classList.remove('auth-mode');const r=registration;let fields='';if(r.step===0)fields=`${select('role','نوع الحساب',{merchant:'تاجر',courier:'مندوب'},r.role)}${input('name','الاسم / اسم النشاط',r.name,'required maxlength="80"')}${input('phone','رقم الهاتف',r.phone,'type="tel" required dir="ltr" placeholder="077xxxxxxxx"')}${input('password','كلمة المرور',r.password,'type="password" required minlength="8" autocomplete="new-password"')}<p class="file-help">الأرقام المسموحة077 و078 و079. يمكن استخدام صيغة +964 أيضاً.</p>`;else if(r.step===1)fields=`${r.role==='merchant'?select('activity','نوع النشاط',{shop:'محل',warehouse:'مخزن',ecommerce:'تجارة إلكترونية — قريباً'},r.activity):r.role==='courier'?`${select('vehicle','نوع المركبة',vehicleNames,r.vehicle)}${input('plate','رقم المركبة',r.plate,'required maxlength="40"')}`:''}${select('province','المحافظة',Object.fromEntries(provinces.map(p=>[p,p])),r.province)}${input('area','المنطقة',r.area,'required')}${input('address','العنوان',r.address,'required')}`;else if(r.step===2)fields=`${coords(r.location)}${r.role==='merchant'?'<label>صورة المحل من الداخل<input type="file" name="inside" accept="image/*" required></label><label>صورة المحل من الخارج<input type="file" name="outside" accept="image/*" required></label>':r.role==='courier'?'<label>الصورة الشخصية<input name="inside" type="file" accept="image/*" required></label>':''}`;else fields=`${row('الاسم',r.name)}${row('الهاتف',r.phone)}${row('الدور',roleNames[r.role])}${row('العنوان',r.province+' — '+r.area+' — '+r.address)}<div class="photo-preview">${r.photos.map(p=>`<img alt="صورة التسجيل" src="${p}">`).join('')}</div><p class="status-note blue">يصبح الحساب جاهزاً بعد إكمال التسجيل. التحقق الآلي عبر SMS غير مربوط في النسخة المحلية.</p>`;
 $('#app').innerHTML=`<section class="surface wizard">${stepper(r.step,['الأساسيات','النشاط','الصور والموقع','المراجعة'])}<form id="register-form" class="form-stack">${fields}<p class="inline-error"></p><div class="wizard-footer">${r.step?button('register-back','السابق'):button('login-page','رجوع')}<button class="primary-button">${r.step===3?'إنشاء الحساب':'التالي'}</button></div></form></section>`;
}
function orderActionForm(o,op,extra={}){if(op==='edit')return startOrder(o.kind,o);if(op==='chat'){return modal('محادثة '+o.id,`<p class="muted">محادثة مستقلة مرتبطة بهذا الطلب فقط.</p>${button('refresh-chat','تحديث المحادثة',`data-id="${o.id}"`)}<div class="stack" style="margin-top:12px">${S.messages.filter(m=>m.orderId===o.id).slice().reverse().map(m=>`<div class="chat-message ${m.owner===S.user.id?'mine':''}">${esc(m.text)}<small>${esc(m.name)} • ${date(m.at)}</small></div>`).join('')||'<p class="muted">لا توجد رسائل بعد.</p>'}</div><form id="action-form" class="form-stack" data-id="${o.id}" data-op="chat" style="margin-top:14px"><label>رسالتك<textarea name="text" required maxlength="2000"></textarea></label><p class="inline-error"></p><button class="primary-button">إرسال إلى محادثة الطلب</button></form>`);}
 const confirm=label=>`<label class="checkbox"><input type="checkbox" name="confirmed" required>${label}</label>`;
 const contents={publish:'سيظهر الطلب للمندوبين المناسبين في النظام المحلي.',unpublish:'سيعود الطلب إلى المسودات ولن يظهر للمندوبين.',delete:'سيُحذف الطلب المحفوظ. الطلب المنشور لا يمكن حذفه بهذه الطريقة.',cancel:'يُلغى الطلب قبل استلام الشحنة.',reserve:'يُحجز الطلب لك وحدك. لا يمكنك حجز طلب ثانٍ حتى استلامه.',depart:'تأكيد التوجه إلى التاجر.',extend:`يُمدد الحجز مرة واحدة بنسبة ${S.settings.extensionPercent}% من المدة الأصلية.`,arrive:'تأكيد وصولك إلى موقع الاستلام يوقف مهلة الوصول.',wait:'الطلب بانتظار التجهيز أو معالجة اختلاف في البيانات.',transit:'تأكيد بدء توصيل الشحنة إلى الزبون.',customer_arrive:'تأكيد الوصول إلى عنوان الزبون.',approve_retry:'الموافقة على موعد المحاولة المقترح: '+date(o.retryAt),return:'تأكيد نقل الطلب إلى مسار الإرجاع.',return_start:'تأكيد بدء رحلة الإرجاع.',return_arrive:'تأكيد الوصول بالشحنة المرتجعة.',partial_approve:'الموافقة على القطع والقيمة المقترحة للتسليم الجزئي.'};
 let fields=contents[op]?`<p>${esc(contents[op])}</p>`:'';
 if(op==='raise_fee'||op==='offer')fields=input('fee','أجرة التوصيل المقترحة (د.ع)',op==='raise_fee'?o.fee+1000:o.fee,'type="number" min="1" required');
 if(op==='release'||op==='fail')fields=select('reason','السبب',{'':'اختر السبب','عدم الرد أو إغلاق الهاتف':'عدم الرد أو إغلاق الهاتف','عدم وجود الزبون':'عدم وجود الزبون','خطأ في العنوان':'خطأ في العنوان','رفض الاستلام أو الدفع':'رفض الاستلام أو الدفع','اختلاف أو مشكلة في الشحنة':'اختلاف أو مشكلة في الشحنة','سبب آخر':'سبب آخر'},'','required')+input('reasonDetails','التوضيح','','maxlength="300"');
 if(op==='pickup')fields=`<p class="status-note">المطلوب دفعه للمرسل: ${money(o.kind==='free'?0:o.amount)} د.ع</p><label class="checkbox"><input type="checkbox" name="inspected" required>راجعت عدد القطع والتغليف والمطابقة وعالجت أي اختلاف.</label><label class="checkbox"><input type="checkbox" name="paid" required>دفعت القيمة المستحقة وتسلمت الشحنة.</label>${input('code','رمز الاستلام من التاجر','','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6"')}`;
 if(op==='deliver')fields=`<p class="status-note blue">المطلوب من الزبون: ${money(customerDue(o))} د.ع</p>${confirm('تم تسليم الشحنة وتحصيل المبلغ أعلاه.')}<label>وصف إثبات التسليم<textarea name="proof" minlength="8" required placeholder="وصف التأكيد في البيئة التجريبية"></textarea></label><p class="file-help">لا توجد رسالة SMS فعلية؛ الإثبات هنا وصف محلي يحتاج ربط مزود تحقق قبل التشغيل.</p>`;
 if(op==='retry')fields=input('when','الموعد المقترح','','type="datetime-local" required');
 if(op==='receive_return')fields='<label class="checkbox"><input type="checkbox" name="inspected" required>فحصت القطع المرتجعة واستلمتها. تبقى التسوية المالية مفتوحة.</label>';
 if(op==='settle_return')fields=`<p>قيمة البضاعة الواجب استردادها: ${money(o.goodsPaid?o.amount-(o.partial?.amount||0):0)} د.ع</p>${input('fees','أجور الذهاب والراجع المسواة',o.fee+o.returnFee,'type="number" min="0" required')}${confirm('استرددت قيمة المرتجع وسُويت الأجور. هذا تأكيد محلي لا ينفذ تحويلاً.')}`;
 if(op==='settle_delivery')fields=`<p>أجرة على المرسل: ${money(o.feePayer==='merchant'?o.fee:0)} د.ع. قيمة تحصيل تُعاد للمرسل: ${money(o.kind==='free'?o.amount:0)} د.ع.</p>${confirm('اكتملت تسوية هذه المبالغ مع المرسل.')}`;
 if(op==='partial_propose')fields=`${input('count','عدد القطع المسلمة','','type="number" min="1" required')}${input('amount','قيمة الجزء المسلم','','type="number" min="1" required')}`;
 if(op==='partial_confirm')fields=confirm('سلمت الجزء المعتمد وحصلت قيمته دون الأجور. تُسوّى الأجور مع الإرجاع.');
 if(op==='rate')fields=select('stars','التقييم',{'5':'★★★★★','4':'★★★★','3':'★★★','2':'★★','1':'★'},'5')+'<label>ملاحظتك<textarea name="text" maxlength="500"></textarea></label>';
 if(op==='accept_offer')fields='<p>قبول هذا العرض يثبت الأجرة ويحجز الطلب إن بقي متاحاً وكان المندوب مؤهلاً.</p>';
 modal('إجراء على '+o.id,`<form id="action-form" class="form-stack" data-id="${o.id}" data-op="${op}" data-offer="${esc(extra.offer||'')}">${fields}<p class="inline-error"></p><button class="primary-button">تأكيد</button></form>`);
}
async function runAction(id,action,data={}){await api(`/api/orders/${encodeURIComponent(id)}/action`,{action,...data});await refresh();if(action==='delete')closeModal();else if(action==='chat')orderActionForm(S.orders.find(o=>o.id===id),'chat');else orderDetail(id);toast('تم تسجيل الإجراء');}
function readiness(){modal('جاهزية المندوب',`<form id="readiness-form" class="form-stack"><label class="checkbox"><input name="available" type="checkbox" ${S.user.available?'checked':''}>متاح لاستلام طلبات</label>${input('budget','الميزانية المتاحة لدفع البضائع',S.user.budget,'type="number" min="0" required')}${input('radius','نطاق الاستلام (كم)',S.user.radius,'type="number" min="1" max="100" required')}${coords(S.user.location)}<p class="inline-error"></p><button class="primary-button">حفظ الجاهزية</button></form>`);}
function profileForm(){const u=S.user;modal('تعديل الملف',`<form id="profile-form" class="form-stack">${input('name','الاسم',u.name,'required')}${select('province','المحافظة',Object.fromEntries(provinces.map(p=>[p,p])),u.province)}${input('area','المنطقة',u.area,'required')}${input('address','العنوان',u.address,'required')}${input('phone2','هاتف احتياطي',u.phone2||'','type="tel" dir="ltr"')}${coords(u.location)}<p class="file-help">يُحفظ التعديل مباشرة مع بقاء المعرف ثابتاً.</p><p class="inline-error"></p><button class="primary-button">حفظ التعديل</button></form>`);}

function mapPlot(groups){if(!groups.length)return '';const lats=groups.map(g=>g.location.lat),lngs=groups.map(g=>g.location.lng),minLat=Math.min(...lats)-.005,maxLat=Math.max(...lats)+.005,minLng=Math.min(...lngs)-.005,maxLng=Math.max(...lngs)+.005;return '<div class="coordinate-map"><svg viewBox="0 0 600 230" role="img" aria-label="مخطط مواقع تقريبي حسب الإحداثيات"><rect width="600" height="230" rx="16" fill="#eff4ff"/><path d="M0 57H600M0 115H600M0 173H600M150 0V230M300 0V230M450 0V230" stroke="#d8e5f1" stroke-width="1"/>'+groups.map(g=>{const x=40+(g.location.lng-minLng)/(maxLng-minLng)*520,y=35+(maxLat-g.location.lat)/(maxLat-minLat)*150;return '<g><circle cx="'+x+'" cy="'+y+'" r="18" fill="#f47d2f"/><text x="'+x+'" y="'+(y+5)+'" text-anchor="middle" fill="white" font-size="14" font-weight="700">'+g.count+'</text><text x="'+x+'" y="'+(y+38)+'" text-anchor="middle" fill="#00567a" font-size="11">'+esc(g.name)+'</text></g>';}).join('')+'</svg><p class="file-help">مخطط إحداثيات تقريبي، لا يعرض الطرق. افتح الموقع في الخرائط للملاحة.</p></div>';}

function localMap(couriers=false){const groups=couriers?S.couriers.map(c=>({id:c.id,name:c.name,location:c.location,count:1})):Object.values(baseOrders().reduce((a,o)=>{a[o.merchant]??={id:o.merchant,name:o.sender.name,location:o.sender.location,count:0,ids:[]};a[o.merchant].count++;a[o.merchant].ids.push(o.id);return a;},{}));modal(couriers?'مواقع المناديب المسجلة':'طلبات كل موقع',`<p class="muted">إحداثيات محفوظة؛ تحديث حركة المندوب يتم عند إرسال موقعه. تجميع العلامة لا يحجز الطلبات.</p>${mapPlot(groups)}<div class="map-list">${groups.map(g=>`<div class="map-pin"><span class="number">${g.count}</span><h3>${esc(g.name)}</h3><p class="info-line">${g.location.lat.toFixed(4)}, ${g.location.lng.toFixed(4)}</p><div class="contact-actions">${maps(g.location)}</div>${g.ids?g.ids.map(id=>button('order',id,`data-id="${id}"`)).join(''):''}</div>`).join('')||'<p>لا توجد مواقع متاحة.</p>'}</div>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='demo')await login(b.dataset.role,{merchant:'07700000001',courier:'07700000002'}[b.dataset.role],'WaselDemo2026!');
 else if(a==='logout'){if(trackingId!==null){navigator.geolocation.clearWatch(trackingId);trackingId=null;}await api('/api/logout',{});localStorage.removeItem('wasel-platform-two-role-snapshot');S=null;authRole=null;closeModal();loginPage();}
 else if(a==='login-page'){registration=null;loginPage();}
 else if(a==='choose-role'){if(!roleNames[b.dataset.role])return;authRole=b.dataset.role;loginPage();}
 else if(a==='choose-again'){authRole=null;loginPage();}
 else if(a==='nav'){if(b.dataset.screen==='new')startOrder();else{screen=b.dataset.screen;wizard=null;filter='all';query='';render();window.scrollTo(0,0);}}
 else if(a==='refresh')await refresh();
 else if(a==='copy-wallet'){try{await navigator.clipboard.writeText(S.user.walletId);toast('تم نسخ رقم المحفظة');}catch{modal('رقم المحفظة',`<p class="wallet-copy-value" dir="ltr">${esc(S.user.walletId)}</p><p class="muted">اضغط مطولاً على الرقم لنسخه.</p>`);}}
 else if(a==='wallet-statement')modal('كشف المحفظة',`${row('الرصيد الحالي',money(S.balance)+' د.ع')}${ledger(S.ledger)}`);
 else if(a==='toggle-password'){const p=document.querySelector('#login-form input[name=password]');const visible=p.type==='password';p.type=visible?'text':'password';b.innerHTML=icon(visible?'visibility_off':'visibility');b.setAttribute('aria-label',visible?'إخفاء كلمة المرور':'إظهار كلمة المرور');b.setAttribute('aria-pressed',String(visible));}
 else if(a==='new-free')startOrder('free');
 else if(a==='order')orderDetail(b.dataset.id);
 else if(a==='filter-open'){const menu=$('#status-menu');if(menu.matches(':popover-open'))menu.hidePopover();else{menu.showPopover();const r=b.getBoundingClientRect(),w=Math.min(340,innerWidth-24),above=r.top-12,below=innerHeight-r.bottom-12;menu.style.width=w+'px';menu.style.maxHeight=Math.min(450,Math.max(above,below))+'px';menu.style.left=Math.max(12,Math.min(r.right-w,innerWidth-w-12))+'px';menu.style.top=(below<350&&above>below?Math.max(12,r.top-menu.offsetHeight-8):r.bottom+8)+'px';b.setAttribute('aria-expanded','true');menu.querySelector('[aria-selected=true]').focus({preventScroll:true});menu.ontoggle=()=>b.setAttribute('aria-expanded',String(menu.matches(':popover-open')));}}
 else if(a==='filter'){filter=b.dataset.value;render();$('#status-trigger')?.focus();}
 else if(a==='wizard-back'){wizard.step--;render();}
 else if(a==='save-order'){b.disabled=true;const data={...wizard.data,publish:b.dataset.publish==='true'};if(offline||!navigator.onLine){if(wizard.id||data.publish)throw Error('يمكن حفظ مسودة جديدة دون نشر فقط أثناء عدم الاتصال');const drafts=readDrafts();drafts.push(data);localStorage.setItem('wasel-offline-'+S.user.id,JSON.stringify(drafts));screen='account';wizard=null;render();toast('حُفظت المسودة على هذا الجهاز');}else{if(wizard.id)await api(`/api/orders/${wizard.id}/action`,{...data,action:'edit'});else await api('/api/orders',data);wizard=null;screen='registry';await refresh();toast('حُفظ الطلب');}}
 else if(a==='sync-draft'){const drafts=readDrafts();await api('/api/orders',{...drafts[Number(b.dataset.index)],publish:false});drafts.splice(Number(b.dataset.index),1);localStorage.setItem('wasel-offline-'+S.user.id,JSON.stringify(drafts));await refresh();toast('حُفظت المسودة في الخادم دون نشر');}
 else if(a==='refresh-chat'){await refresh(false);orderActionForm(S.orders.find(o=>o.id===b.dataset.id),'chat');}
 else if(a==='order-action')orderActionForm(S.orders.find(o=>o.id===b.dataset.id),b.dataset.op,{offer:b.dataset.offer});
 else if(a==='readiness')readiness();
 else if(a==='tracking'){if(trackingId!==null){navigator.geolocation.clearWatch(trackingId);trackingId=null;render();toast('توقفت مشاركة الموقع');}else{if(!navigator.geolocation)throw Error('الموقع غير مدعوم');trackingId=navigator.geolocation.watchPosition(async pos=>{if(Date.now()-lastLocationSent<15000)return;lastLocationSent=Date.now();try{await api('/api/profile',{action:'location',location:{lat:pos.coords.latitude,lng:pos.coords.longitude}});await refresh(false);}catch(err){toast(err.message);}},()=>{navigator.geolocation.clearWatch(trackingId);trackingId=null;toast('تعذرت مشاركة الموقع؛ راجع إذن المتصفح');},{enableHighAccuracy:true,maximumAge:10000,timeout:20000});render();toast('المشاركة تعمل أثناء فتح التطبيق فقط');}}
 else if(a==='edit-profile')profileForm();
 else if(a==='preferences'){await api('/api/profile',{action:'preferences',motivational:S.user.motivational===false});await refresh();}
 else if(a==='nearby')localMap(true);
 else if(a==='merchant-map')localMap();
 else if(a==='notifications')modal('الإشعارات',`<ul class="notice-list">${S.notifications.map(n=>`<li>${esc(n.text)}<small class="muted" style="display:block">${date(n.at)} ${esc(n.orderId||'')}</small></li>`).join('')||'<li>لا توجد إشعارات بعد.</li>'}</ul><p class="file-help">تظهر التحديثات أثناء فتح التطبيق. إشعارات الدفع خارج التطبيق تحتاج إعداد خدمة Push.</p>`);
 else if(a==='gps'){if(!navigator.geolocation)throw Error('الموقع غير مدعوم في المتصفح');const form=b.closest('form');b.disabled=true;navigator.geolocation.getCurrentPosition(p=>{form.elements.lat.value=p.coords.latitude;form.elements.lng.value=p.coords.longitude;b.disabled=false;toast('تم تحديد الموقع؛ راجع العنوان والمنطقة');},()=>{b.disabled=false;toast('تعذر تحديد الموقع؛ يمكنك إدخال الإحداثيات يدوياً');},{enableHighAccuracy:true,timeout:15000});}
 else if(a==='register'){registration={step:0,role:authRole||'merchant',activity:'shop',vehicle:'sedan',province:'بغداد',photos:[],location:{lat:33.3,lng:44.43}};registrationView();}
 else if(a==='register-back'){registration.step--;registrationView();}
 else if(a==='install'){if(installPrompt){const p=installPrompt;installPrompt=null;await p.prompt();}else modal('تثبيت واصل','<p>Android: قائمة Chrome ← تثبيت التطبيق.</p><p>iPhone: مشاركة في Safari ← إضافة إلى الشاشة الرئيسية.</p><p class="file-help">على الهاتف يحتاج التطبيق استضافة HTTPS. الخادم الحالي محلي على الكمبيوتر.</p>');}
 }catch(err){toast(err.message);b.disabled=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const f=Object.fromEntries(new FormData(form));const error=form.querySelector('.inline-error');if(error)error.textContent='';const submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{
 if(form.id==='login-form')await login(f.role,f.phone,f.password);
 else if(form.id==='courier-register-form')reviewCourierRegistration();
 else if(form.id==='order-form'){gatherOrder(form);if(wizard.step===1&&wizard.data.kind==='free'){const photo=await imageData(form.elements.photo.files[0]);if(photo)wizard.data.photo=photo;}wizard.step++;render();window.scrollTo(0,0);}
 else if(form.id==='register-form'){const r=registration;Object.assign(r,Object.fromEntries(Object.entries(f).filter(([k,v])=>typeof v==='string')));if(r.step===1&&r.role==='merchant'&&r.activity==='ecommerce')throw Error('تسجيل التجارة الإلكترونية معطل حالياً؛ سيتاح لاحقاً');if(r.step===2){r.location={lat:Number(f.lat),lng:Number(f.lng)};r.photos=[];for(const k of ['inside','outside'])if(form.elements[k]?.files[0])r.photos.push(await imageData(form.elements[k].files[0]));}if(r.step===3){await api('/api/register',r);await login(r.role,r.phone,r.password);toast('تم إنشاء الحساب');registration=null;}else{r.step++;registrationView();}}
 else if(form.id==='action-form'){for(const name of ['confirmed','inspected','paid'])if(form.elements[name])f[name]=form.elements[name].checked;if(f.reasonDetails)f.reason+=' — '+f.reasonDetails;if(form.dataset.op==='retry')f.when=new Date(f.when).toISOString();await runAction(form.dataset.id,form.dataset.op,{...f,offer:form.dataset.offer});}
 else if(form.id==='readiness-form'){await api('/api/profile',{...f,action:'readiness',available:form.elements.available.checked,location:{lat:Number(f.lat),lng:Number(f.lng)}});closeModal();await refresh();}
 else if(form.id==='profile-form'){await api('/api/profile',{...f,action:'profile',location:{lat:Number(f.lat),lng:Number(f.lng)}});closeModal();await refresh();}
 }catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.name==='savedCustomer'&&e.target.value!==''){wizard.data.recipient=structuredClone(S.user.customers[Number(e.target.value)]);render();}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='order-search'){const pos=e.target.selectionStart;query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const input=$('#order-search');input.focus();input.setSelectionRange(pos,pos);},250);}});
document.addEventListener('keydown',e=>{const menu=$('#status-menu');if(!menu?.matches(':popover-open'))return;const options=[...menu.querySelectorAll('[role=option]')],index=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[next].focus();}if(e.key==='Escape')$('#status-trigger').setAttribute('aria-expanded','false');});
$('#close-dialog').addEventListener('click',closeModal);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('offline',()=>{offline=true;if(S&&!wizard&&!$('#app-dialog').open)render();});
window.addEventListener('online',()=>{if(S)refresh(!wizard&&!$('#app-dialog').open);});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
setInterval(()=>{if(S&&!wizard&&!registration&&!$('#app-dialog').open&&!$('#status-menu')?.matches(':popover-open')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))refresh();},12000);
