// Adapted from the supplied Bal3D interaction, keeping the existing wallet artwork.
function stopWalletMotion(){if(initWalletMotion.cleanup){initWalletMotion.cleanup();initWalletMotion.cleanup=null;}}
function initWalletMotion(){
 const card=document.querySelector('.orbit-wallet');if(!card)return;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 if(reduced.matches)return;
 const wrap=document.createElement('div');wrap.className='orbit-motion';card.before(wrap);wrap.append(card);
 const shine=document.createElement('span');shine.className='orbit-shimmer';shine.setAttribute('aria-hidden','true');card.append(shine);
 const amount=card.querySelector('.orbit-balance strong'),target=S.balance,start=performance.now();
 let frame=0,timer=0;amount.setAttribute('aria-label',money(target));
 const count=now=>{if(!card.isConnected)return;const p=Math.min(1,(now-start)/850);amount.textContent=money(Math.round(target*(1-Math.pow(1-p,3))));if(p<1)frame=requestAnimationFrame(count);};
 frame=requestAnimationFrame(count);
 const move=e=>{if(reduced.matches||e.target.closest('button'))return;clearTimeout(timer);const r=wrap.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));card.classList.add('is-tilting');card.style.setProperty('--wallet-x',((.5-y)*8)+'deg');card.style.setProperty('--wallet-y',((x-.5)*10)+'deg');card.style.setProperty('--wallet-light-x',x*100+'%');card.style.setProperty('--wallet-light-y',y*100+'%');};
 const reset=()=>{clearTimeout(timer);card.classList.remove('is-tilting');card.style.setProperty('--wallet-x','0deg');card.style.setProperty('--wallet-y','0deg');};
 const up=()=>{timer=setTimeout(reset,450);};
 const visibility=()=>{if(document.hidden)reset();};
 const changed=()=>{reset();cancelAnimationFrame(frame);amount.textContent=money(target);};
 for(const event of ['pointerdown','pointermove'])wrap.addEventListener(event,move,{passive:true});
 for(const event of ['pointerleave','pointercancel'])wrap.addEventListener(event,reset);
 wrap.addEventListener('pointerup',up);document.addEventListener('visibilitychange',visibility);reduced.addEventListener('change',changed);
 initWalletMotion.cleanup=()=>{cancelAnimationFrame(frame);clearTimeout(timer);for(const event of ['pointerdown','pointermove'])wrap.removeEventListener(event,move);for(const event of ['pointerleave','pointercancel'])wrap.removeEventListener(event,reset);wrap.removeEventListener('pointerup',up);document.removeEventListener('visibilitychange',visibility);reduced.removeEventListener('change',changed);};
}
